import React from 'react'
import { View, Text, TouchableOpacity } from 'react-native'

import { useContexState } from '../../hooks/context';
import { styles } from './styles'

import api from '../../services/api';
console.log('render--teste')
interface CardsProps {
    position: number,
    listItemProps: {
        data: { lineCards: number, id: string };
        list?: {
            [key: string]: [{
                id: number;
                name: string;
                phone: string;
                price: number;
            }]
        };
    }
}

export function Cards({ listItemProps, position }: CardsProps) {
    const { refreshGetList, setRefreshGetList } = useContexState();

    const cardNumber = String(listItemProps.data.lineCards + position);
    const randomText = Math.random().toString(36).substr(2, 5);

    function cardPost() {
        api.post("register", {
            number: Number(cardNumber),
            name: randomText,
            phone: '(00)000000000',
        }).then((response) => {
            setRefreshGetList(refreshGetList ? false : true);
        });
    }

    function colorSelect() {
        if (listItemProps.list?.[cardNumber]) {
            if (listItemProps.list?.[cardNumber][0].price !== 0) {
                return { backgroundColor: '#26A744' }
            } else {
                return { backgroundColor: '#17A2B7' }
            }
        } else {
            return { backgroundColor: '#fff', color: '#121212' }
        }
    }

    return (
        <TouchableOpacity onPress={cardPost}>
            <View>
                <Text style={[styles.listText, colorSelect()
                ]}>
                    {(`0000${cardNumber}`).slice(-4)}
                </Text>
            </View>
        </TouchableOpacity>
    )
}
